<template><div class="min-h-full bg-background p-3 md:p-4"><div class="mx-auto max-w-7xl"><div class="mb-4 flex items-end justify-between gap-3"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Offplan financing</p><h1 class="text-lg font-bold text-slate-900">Bank Financing</h1></div><button @click="addOpen=true" class="bg-primary px-3 py-1.5 text-xs font-semibold text-white">+ New financing</button></div><div class="mb-3 grid grid-cols-2 gap-2 md:grid-cols-4"><div class="h-14 border border-slate-200 bg-white px-3 py-2"><p class="text-[10px] uppercase tracking-wide text-slate-500">Total</p><p class="text-base font-bold text-slate-900">{{items.length}}</p></div><div class="h-14 border border-slate-200 bg-white px-3 py-2"><p class="text-[10px] uppercase tracking-wide text-slate-500">Active</p><p class="text-base font-bold text-slate-900">{{count('active')}}</p></div><div class="h-14 border border-slate-200 bg-white px-3 py-2"><p class="text-[10px] uppercase tracking-wide text-slate-500">Approved</p><p class="text-base font-bold text-slate-900">{{count('approved')}}</p></div><div class="h-14 border border-slate-200 bg-white px-3 py-2"><p class="text-[10px] uppercase tracking-wide text-slate-500">Pending</p><p class="text-base font-bold text-slate-900">{{count('pending')}}</p></div></div><div class="mb-3 flex gap-2 border border-slate-200 bg-white p-2"><input v-model="search" class="min-w-0 flex-1 border border-slate-200 px-2.5 py-1.5 text-xs outline-none" placeholder="Search bank, account, status or application"/><button @click="load" class="border border-slate-300 px-3 py-1.5 text-xs">Refresh</button></div><div v-if="error" class="mb-3 border border-red-200 bg-red-50 p-2 text-xs text-red-700">{{error}}</div><div class="overflow-x-auto border border-slate-200 bg-white"><table class="min-w-full text-left text-xs"><thead class="bg-slate-50"><tr><th class="px-3 py-2 font-semibold">Customer · Owner · Property</th><th class="px-3 py-2 font-semibold">Bank</th><th class="px-3 py-2 font-semibold">Account</th><th class="px-3 py-2 font-semibold">Loan</th><th class="px-3 py-2 font-semibold">Rate</th><th class="px-3 py-2 font-semibold">Status</th><th class="px-3 py-2 text-right font-semibold">Actions</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id" class="border-t hover:bg-slate-50"><td class="min-w-[180px] px-3 py-2"><div class="space-y-1.5"><div><p class="text-[9px] font-semibold uppercase tracking-wide text-slate-400">Customer</p><router-link :to="{name:'OffplanBankFinancing-detail',params:{id:x.id}}" class="text-xs font-medium text-primary hover:underline">{{customerName(x.application?.customer)}}</router-link></div><div><p class="text-[9px] font-semibold uppercase tracking-wide text-slate-400">Owner</p><router-link :to="{name:'OffplanBankFinancing-detail',params:{id:x.id}}" class="text-xs text-primary hover:underline">{{customerName(x.application?.offplan_property?.owner||x.application?.offplan_property?.property_zone?.owner)}}</router-link></div><div><p class="text-[9px] font-semibold uppercase tracking-wide text-slate-400">Offplan property</p><router-link :to="{name:'OffplanBankFinancing-detail',params:{id:x.id}}" class="text-xs text-primary hover:underline">{{propertyName(x.application?.offplan_property)}}</router-link></div></div></td><td class="px-3 py-2 font-semibold">{{x.bank_name||'—'}}</td><td class="px-3 py-2">{{x.loan_account_number||'—'}}</td><td class="px-3 py-2">{{x.loan_amount||'—'}}</td><td class="px-3 py-2">{{x.interest_rate||'—'}}</td><td class="px-3 py-2"><span class="border border-primary/20 bg-primary/10 px-1.5 py-0.5 text-[10px] font-semibold text-primary">{{display(x.loan_status)}}</span></td><td class="px-3 py-2 text-right"><router-link :to="{name:'OffplanBankFinancing-detail',params:{id:x.id}}" class="border border-slate-300 px-2 py-1 text-[10px]">View</router-link> <button @click="edit(x.id)" class="border border-primary px-2 py-1 text-[10px] text-primary">Edit</button></td></tr></tbody></table><div v-if="!loading&&!filtered.length" class="p-8 text-center text-xs text-slate-500">No financing records found.</div></div></div><AddOffplanBankFinancing :open="addOpen" @close="addOpen=false" @saved="load"/><EditOffplanBankFinancing :open="editOpen" :id="selectedId" @close="editOpen=false" @saved="load"/></div></template>
<script>import AddOffplanBankFinancing from "./AddOffplanBankFinancing.vue";import EditOffplanBankFinancing from "./EditOffplanBankFinancing.vue";export default{name:"ViewOffplanBankFinancing",components:{AddOffplanBankFinancing,EditOffplanBankFinancing},data(){return{items:[],search:"",loading:false,error:"",addOpen:false,editOpen:false,selectedId:null}},computed:{filtered(){const q=this.search.toLowerCase().trim();return q?this.items.filter(x=>[x.id,x.bank_name,x.loan_account_number,x.loan_amount,x.loan_status,x.application?.id,x.application?.application_status,x.application?.agreed_price,this.customerName(x.application?.customer),x.application?.customer?.phone_number,this.propertyName(x.application?.offplan_property),x.application?.offplan_property?.developer,x.application?.offplan_property?.property_zone?.name,this.customerName(x.application?.offplan_property?.owner),this.customerName(x.application?.offplan_property?.manager)].join(" ").toLowerCase().includes(q)):this.items}},mounted(){this.load()},methods:{async load(){this.loading=true;this.error="";try{this.items=await this.$getOffplanBankFinancings()}catch(e){this.error=e?.message||"Unable to load financing."}finally{this.loading=false}},edit(id){this.selectedId=id;this.editOpen=true},count(s){return this.items.filter(x=>String(x.loan_status||"").toLowerCase()===s).length},display(v){return String(v||"—").replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},customerName(v){if(!v)return "Not provided";if(typeof v==="string")return v;return [v.first_name,v.middle_name,v.last_name].filter(Boolean).join(" ")||v.full_name||v.name||v.email||"Not provided"},propertyName(p){if(!p)return "Property details unavailable";const zone=p.property_zone?.name;return [zone,p.property_type,p.id?`Property #${p.id}`:""].filter(Boolean).join(" · ")||"Offplan property"},money(v){if(v===null||v===undefined||v==="")return "—";const n=Number(v);return Number.isFinite(n)?n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}):v}}};</script>